import{_ as e,o as t,c as r,a2 as i}from"./chunks/framework.D8Tso2Ul.js";const p=JSON.parse('{"title":"¿Qué es Build & Serve?","description":"","frontmatter":{},"headers":[],"relativePath":"guia-inicio/index.md","filePath":"guia-inicio/index.md"}'),o={name:"guia-inicio/index.md"};function n(d,a,l,s,u,c){return t(),r("div",null,[...a[0]||(a[0]=[i('<h1 id="¿que-es-build-serve" tabindex="-1">¿Qué es Build &amp; Serve? <a class="header-anchor" href="#¿que-es-build-serve" aria-label="Permalink to &quot;¿Qué es Build &amp; Serve?&quot;">​</a></h1><p><strong>Build &amp; Serve</strong> es una plataforma SaaS multi-tenant para la gestión digital de Seguridad y Salud en el Trabajo (SST) en obras de construcción chilenas. Reemplaza el papeleo por un sistema único, trazable y con cumplimiento integrado del <strong>Supremo Decreto 44 (DS 44)</strong>.</p><p>Desarrollada por <strong>The Code Cookers</strong> para el Hackathon CChC 2025 — <em>Seguridad sin Papeleo</em>, en colaboración con la Cámara Chilena de la Construcción.</p><h2 id="para-quien-es" tabindex="-1">Para quién es <a class="header-anchor" href="#para-quien-es" aria-label="Permalink to &quot;Para quién es&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Perfil</th><th>Qué resuelve</th></tr></thead><tbody><tr><td>Empresas constructoras</td><td>Cumplimiento del DS 44 sin carpetas físicas</td></tr><tr><td>Prevencionistas</td><td>Gestión centralizada de documentos, matrices y capacitaciones</td></tr><tr><td>Supervisores</td><td>Captura de firmas y registro de actividades en terreno</td></tr><tr><td>Trabajadores</td><td>Firma de documentos y asistencia desde el móvil, incluso sin conexión</td></tr></tbody></table><h2 id="que-problema-resuelve" tabindex="-1">Qué problema resuelve <a class="header-anchor" href="#que-problema-resuelve" aria-label="Permalink to &quot;Qué problema resuelve&quot;">​</a></h2><ul><li><strong>Papeleo disperso</strong> → documentos centralizados y firmados digitalmente.</li><li><strong>Cumplimiento manual del DS 44</strong> → documentos obligatorios precreados por fase.</li><li><strong>Firmas en papel</strong> → firma digital con trazabilidad (PIN + IP + timestamp).</li><li><strong>Sin conectividad en obra</strong> → firma offline con sincronización automática.</li><li><strong>Matrices de riesgo lentas de elaborar</strong> → generación asistida por IA (MIPPER).</li></ul><h2 id="como-empezar" tabindex="-1">Cómo empezar <a class="header-anchor" href="#como-empezar" aria-label="Permalink to &quot;Cómo empezar&quot;">​</a></h2><ol><li><a href="/manual/guia-inicio/instalacion.html">Instalación y configuración</a> — levantar la plataforma.</li><li><a href="/manual/guia-inicio/primeros-pasos.html">Primeros pasos</a> — recorrido inicial.</li><li><a href="/manual/guia-inicio/onboarding.html">Onboarding de tenant</a> — registrar una empresa.</li></ol><h2 id="mapa-de-la-documentacion" tabindex="-1">Mapa de la documentación <a class="header-anchor" href="#mapa-de-la-documentacion" aria-label="Permalink to &quot;Mapa de la documentación&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Sección</th><th>Contenido</th></tr></thead><tbody><tr><td><a href="/manual/ds44/">DS44 &amp; Normativa</a></td><td>Qué exige el DS 44 y cómo se cumple</td></tr><tr><td><a href="/manual/modulos/">Módulos</a></td><td>Los 11 módulos de la plataforma</td></tr><tr><td><a href="/manual/roles/">Roles</a></td><td>Permisos por rol de usuario</td></tr><tr><td><a href="/manual/api/">API</a></td><td>Referencia REST</td></tr><tr><td><a href="/manual/arquitectura/">Arquitectura</a></td><td>Modelo de datos y multi-tenant</td></tr></tbody></table>',11)])])}const h=e(o,[["render",n]]);export{p as __pageData,h as default};
